            if existing_dashboard:
                db.session.delete(existing_dashboard)
                db.session.commit()

        dashboard = Dashboard(
            dashboard_title=dashboard_title,
            slug=slug,
            owners=obj_owners,
            roles=obj_roles,
            position_json=position_json,
            css=css,
