    def create_import_v1_zip_file(asset_type: str, **kwargs) -> BytesIO:
        asset_configs = {
            "databases": (kwargs.get("databases"), database_config, True),
            "datasets": (
                kwargs.get("datasets"),
                dataset_config,
                asset_type != "database",
            ),
            "charts": (
